import chess
import chess.pgn
import json
import io
import re
import sys

def repair_game(pgn_text, game_id):
    """Parse and repair a corrupted PGN game."""
    lines = pgn_text.strip().split('\n')
    header_lines = []
    move_lines = []
    in_moves = False

    for line in lines:
        line = line.strip()
        if line.startswith('['):
            header_lines.append(line)
        elif line:
            if not in_moves:
                in_moves = True
            move_lines.append(line)

    move_text = ' '.join(move_lines)
    # Remove result codes from move text
    result_match = re.search(r'(1-0|0-1|1/2-1/2|\*)\s*$', move_text)
    result = result_match.group(1) if result_match else '*'
    move_text = re.sub(r'(1-0|0-1|1/2-1/2|\*)\s*$', '', move_text).strip()

    # Split into individual tokens
    tokens = move_text.split()

    board = chess.Board()
    repaired_moves = []
    errors_found = []

    i = 0
    while i < len(tokens):
        token = tokens[i]
        # Skip move numbers like "1.", "16.", etc.
        if re.match(r'^\d+\.$', token):
            i += 1
            continue

        # Try to parse the move
        try:
            move = board.parse_san(token)
            board.push(move)
            repaired_moves.append(token)
            i += 1
        except Exception as e:
            # Try to fix by replacing invalid rank digits
            fixed = False
            # Find invalid squares (file followed by non-valid rank)
            for m in re.finditer(r'([a-h])([^1-8])', token):
                file_char = m.group(1)
                for rank in '12345678':
                    candidate = token[:m.start()] + file_char + rank + token[m.end():]
                    try:
                        move = board.parse_san(candidate)
                        board.push(move)
                        repaired_moves.append(candidate)
                        errors_found.append(f"illegal move {token} -> {candidate}")
                        fixed = True
                        break
                    except:
                        pass
                if fixed:
                    break

            if not fixed:
                errors_found.append(f"unfixable move {token}")
                break

            i += 1

    # Build repaired PGN with proper formatting
    repaired_pgn = '\n'.join(header_lines) + '\n\n'
    move_parts = []
    for idx, move in enumerate(repaired_moves):
        if idx % 2 == 0:
            move_num = idx // 2 + 1
            move_parts.append(f"{move_num}. {move}")
        else:
            move_parts.append(move)
    repaired_pgn += ' '.join(move_parts) + f' {result}'

    # Analyze - replay and find critical position
    board2 = chess.Board()
    for move_str in repaired_moves:
        try:
            move = board2.parse_san(move_str)
            board2.push(move)
        except:
            pass

    # Find critical position
    critical_move = len(repaired_moves)
    critical_eval = 0.0

    if board2.is_checkmate():
        critical_eval = 99.0 if board2.turn() == chess.BLACK else -99.0
    elif board2.is_stalemate():
        critical_eval = 0.0
    else:
        # Material evaluation
        piece_values = {1: 1, 2: 3, 3: 3, 4: 5, 5: 9}
        for square in chess.SQUARES:
            piece = board2.piece_at(square)
            if piece:
                val = piece_values.get(piece.piece_type, 0)
                if piece.color == chess.WHITE:
                    critical_eval += val
                else:
                    critical_eval -= val

    eval_str = f"+{critical_eval:.1f}" if critical_eval >= 0 else f"{critical_eval:.1f}"

    return {
        "game_id": game_id,
        "original_pgn": pgn_text.strip(),
        "repaired_pgn": repaired_pgn.strip(),
        "errors_found": errors_found,
        "critical_position": {"move_number": critical_move, "evaluation": eval_str}
    }

def evaluate_position(board, depth=3):
    """Evaluate position using material + basic positional factors."""
    piece_values = {
        chess.PAWN: 100,
        chess.KNIGHT: 320,
        chess.BISHOP: 330,
        chess.ROOK: 500,
        chess.QUEEN: 900,
        chess.KING: 20000
    }

    if board.is_checkmate():
        return -99999 if board.turn() else 99999
    if board.is_stalemate() or board.is_insufficient_material():
        return 0

    score = 0
    for square in chess.SQUARES:
        piece = board.piece_at(square)
        if piece:
            val = piece_values.get(piece.piece_type, 0)
            score += val if piece.color == chess.WHITE else -val

    return score

def minimax(board, depth, alpha, beta, maximizing):
    """Minimax with alpha-beta pruning."""
    if depth == 0 or board.is_game_over():
        return evaluate_position(board)

    if maximizing:
        max_eval = -999999
        for move in board.legal_moves:
            board.push(move)
            eval = minimax(board, depth - 1, alpha, beta, False)
            board.pop()
            max_eval = max(max_eval, eval)
            alpha = max(alpha, eval)
            if beta <= alpha:
                break
        return max_eval
    else:
        min_eval = 999999
        for move in board.legal_moves:
            board.push(move)
            eval = minimax(board, depth - 1, alpha, beta, True)
            board.pop()
            min_eval = min(min_eval, eval)
            beta = min(beta, eval)
            if beta <= alpha:
                break
        return min_eval

def find_mate_sequence(board, max_depth=8):
    """Find a forced mate sequence."""
    if board.is_checkmate():
        return []
    if board.is_game_over():
        return None

    best_seq = None
    best_depth = max_depth + 1

    for move in board.legal_moves:
        board.push(move)
        if board.is_checkmate():
            board.pop()
            return [board.san(move)]

        # Check if opponent has any move that doesn't lead to mate
        all_lead_to_mate = True
        for reply in board.legal_moves:
            board.push(reply)
            result = find_mate_sequence(board, max_depth - 2)
            board.pop()
            if result is None or len(result) > max_depth - 2:
                all_lead_to_mate = False
                break

        if all_lead_to_mate and board.legal_moves:
            # Get best reply and continue
            best_reply = None
            best_reply_seq = None
            for reply in board.legal_moves:
                board.push(reply)
                seq = find_mate_sequence(board, max_depth - 2)
                board.pop()
                if seq is not None and (best_reply_seq is None or len(seq) < len(best_reply_seq)):
                    best_reply = board.san(reply)
                    best_reply_seq = seq

            if best_reply_seq is not None and len([board.san(move)] + [best_reply] + best_reply_seq) <= max_depth:
                candidate = [board.san(move)] + [best_reply] + best_reply_seq
                if best_seq is None or len(candidate) < len(best_seq):
                    best_seq = candidate

        board.pop()

    return best_seq

def solve_puzzle(puzzle):
    """Solve a chess puzzle."""
    fen = puzzle["fen"]
    board = chess.Board(fen)

    if board.is_checkmate():
        return {"puzzle_id": puzzle["id"], "best_move": "*", "continuation": [], "mate_in": 0}

    # Try to find mate sequence first
    mate_seq = find_mate_sequence(board, max_depth=8)

    if mate_seq:
        halfmoves = len(mate_seq)
        # mate_in counts moves by the side to move
        side_to_move = fen.split()[1] == 'w'
        if side_to_move:
            mate_in = (halfmoves + 1) // 2
        else:
            mate_in = halfmoves // 2 + (1 if halfmoves % 2 else 0)
        return {
            "puzzle_id": puzzle["id"],
            "best_move": mate_seq[0],
            "continuation": mate_seq,
            "mate_in": mate_in
        }

    # Fallback: find best move by minimax
    best_move = None
    best_score = -999999

    for move in board.legal_moves:
        board.push(move)
        score = minimax(board, 3, -999999, 999999, False)
        board.pop()
        if score > best_score:
            best_score = score
            best_move = board.san(move)

    if best_move:
        # Get continuation
        board2 = chess.Board(fen)
        move_obj = board2.parse_san(best_move)
        cont = [best_move]
        board2.push(move_obj)

        # Get a few more moves
        for _ in range(4):
            if board2.is_game_over():
                break
            best_reply = None
            best_reply_score = -999999 if board2.turn() else 999999
            for move in board2.legal_moves:
                board2.push(move)
                score = minimax(board2, 2, -999999, 999999, not board2.turn())
                board2.pop()
                if board2.turn():
                    if score > best_reply_score:
                        best_reply_score = score
                        best_reply = board2.san(move)
                else:
                    if score < best_reply_score:
                        best_reply_score = score
                        best_reply = board2.san(move)

            if best_reply:
                move_obj = board2.parse_san(best_reply)
                cont.append(best_reply)
                board2.push(move_obj)

        return {
            "puzzle_id": puzzle["id"],
            "best_move": best_move,
            "continuation": cont,
            "mate_in": None
        }

    return {"puzzle_id": puzzle["id"], "best_move": "", "continuation": [], "mate_in": None}

def main():
    with open("/workdir/data/games.pgn") as f:
        pgn_text = f.read()

    with open("/workdir/data/puzzles.json") as f:
        puzzles = json.load(f)

    # Split games by consecutive blank lines
    game_blocks = re.split(r'\n{2,}', pgn_text.strip())
    game_blocks = [b.strip() for b in game_blocks if b.strip()]

    repaired_games = []
    total_errors = 0

    for idx, block in enumerate(game_blocks):
        if not block.strip():
            continue
        result = repair_game(block.strip(), idx + 1)
        repaired_games.append(result)
        total_errors += len(result["errors_found"])

    # Solve puzzles
    puzzle_solutions = []
    for puzzle in puzzles:
        print(f"Solving puzzle {puzzle['id']}...", file=sys.stderr)
        sol = solve_puzzle(puzzle)
        puzzle_solutions.append(sol)
        print(f"  Result: {sol}", file=sys.stderr)

    output = {
        "repaired_games": repaired_games,
        "puzzle_solutions": puzzle_solutions,
        "analysis_summary": {
            "games_processed": len(repaired_games),
            "errors_fixed": total_errors,
            "puzzles_solved": len(puzzle_solutions)
        }
    }

    with open("/workdir/chess_analysis.json", "w") as f:
        json.dump(output, f, indent=2)

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
