    if board.is_checkmate():
        return []
    if board.is_game_over():
        return None
    if ply_left == 0:
        return None

    moves = list(board.legal_moves)
    if not moves:
        return None if not board.is_checkmate() else []

    for move in moves:
        board.push(move)
        san = board.san(move)

        if board.is_checkmate():
            board.pop()
            return [san]

        if is_attacking:
            # Attacker's move - need ALL opponent replies to lead to mate
            opponent_moves = list(board.legal_moves)
            all_mate = True
            best_reply_seq = None

            for reply in opponent_moves:
                board.push(reply)
                seq = mate_search(board, ply_left - 1, False)
                board.pop()
                if seq is None:
                    all_mate = False
                    break
                if best_reply_seq is None or len(seq) < len(best_reply_seq):
                    best_reply_seq = seq

            if all_mate and best_reply_seq is not None:
                # Find which reply gives shortest continuation
                best_reply_san = None
                for reply in opponent_moves:
                    board.push(reply)
                    seq = mate_search(board, ply_left - 1, False)
                    board.pop()
                    if seq == best_reply_seq:
                        best_reply_san = board.san(reply)
                        break

                if best_reply_san:
                    board.pop()
                    return [san, best_reply_san] + best_reply_seq
        else:
            # Defender's move - need to find the move that still leads to mate
            seq = mate_search(board, ply_left - 1, True)
