    lines = pgn_text.strip().split('\n')
    header_lines = []
    move_lines = []
    in_moves = False

    for line in lines:
        stripped = line.strip()
        if stripped.startswith('['):
            header_lines.append(stripped)
        elif stripped:
            if not in_moves:
                in_moves = True
            move_lines.append(stripped)

    move_text = ' '.join(move_lines)
    result_match = re.search(r'(1-0|0-1|1/2-1/2|\*)\s*$', move_text)
    result = result_match.group(1) if result_match else '*'
    move_text = re.sub(r'(1-0|0-1|1/2-1/2|\*)\s*$', '', move_text).strip()

    tokens = move_text.split()
    raw_moves = [t for t in tokens if not re.match(r'^\d+\.$', t)]

    def get_fixes(token, board):
        """Get all possible fixes for a corrupted move."""
        try:
            move = board.parse_san(token)
            return [(token, move, 0)]
        except:
            pass

        fixes = []
        # Try fixing rank digit only
        for m in re.finditer(r'([a-h])([^1-8])', token):
            file_char = m.group(1)
            for rank in '12345678':
                candidate = token[:m.start()] + file_char + rank + token[m.end():]
                try:
                    move = board.parse_san(candidate)
                    fixes.append((candidate, move, 1))
                except:
                    pass

        # Try all legal moves with same piece type
        if not fixes:
            piece_type = token[0].upper()
            piece_map = {'K': chess.KING, 'Q': chess.QUEEN, 'R': chess.ROOK, 'B': chess.BISHOP, 'N': chess.KNIGHT}
            if piece_type in piece_map:
                target_type = piece_map[piece_type]
                for move in board.legal_moves:
                    if board.piece_at(move.from_square).piece_type == target_type:
                        fixes.append((board.san(move), move, 2))

        return fixes

    # Backtracking repair
    def repair(idx, board, fixed_moves, errors):
        if idx == len(raw_moves):
            return True

        token = raw_moves[idx]
        fixes = get_fixes(token, board)

        if not fixes:
            return False

        # Sort by priority
        fixes.sort(key=lambda x: x[2])

        for candidate, move, priority in fixes:
            san_before = board.san(move) if priority > 0 else candidate
            board.push(move)
            fixed_moves.append(san_before)
            if candidate != token:
                errors.append(f"illegal move {token} -> {candidate}")
            if repair(idx + 1, board, fixed_moves, errors):
                return True
            board.pop()
            fixed_moves.pop()
            if candidate != token:
                errors.pop()

        return False

    board = chess.Board()
    repaired_moves = []
    errors_found = []

    if not repair(0, board, repaired_moves, errors_found):
        pass  # Partial repair

    repaired_pgn = '\n'.join(header_lines) + '\n\n'
    move_parts = []
    for idx, move in enumerate(repaired_moves):
        if idx % 2 == 0:
            move_num = idx // 2 + 1
            move_parts.append(f"{move_num}. {move}")
        else:
            move_parts.append(move)
    repaired_pgn += ' '.join(move_parts) + f' {result}'

    board2 = chess.Board()
    for move_str in repaired_moves:
        try:
            move = board2.parse_san(move_str)
            board2.push(move)
        except:
            pass

    critical_move = len(repaired_moves)
    critical_eval = 0.0
    if board2.is_checkmate():
        critical_eval = 99.0 if board2.turn == chess.BLACK else -99.0
    elif board2.is_stalemate():
        critical_eval = 0.0
    else:
        piece_values = {1: 1, 2: 3, 3: 3, 4: 5, 5: 9}
        for square in chess.SQUARES:
            piece = board2.piece_at(square)
            if piece:
                val = piece_values.get(piece.piece_type, 0)
                if piece.color == chess.WHITE:
                    critical_eval += val
                else:
                    critical_eval -= val

    eval_str = f"+{critical_eval:.1f}" if critical_eval >= 0 else f"{critical_eval:.1f}"

    return {
        "game_id": game_id,
        "original_pgn": pgn_text.strip(),
        "repaired_pgn": repaired_pgn.strip(),
        "errors_found": errors_found,
        "critical_position": {"move_number": critical_move, "evaluation": eval_str}
    }

def solve_puzzle(puzzle):
    fen = puzzle["fen"]
    board = chess.Board(fen)
    if board.is_checkmate():
        return {"puzzle_id": puzzle["id"], "best_move": "*", "continuation": [], "mate_in": 0}

    desc = puzzle.get("description", "").lower()

    if "mate" in desc:
        mate_in_num = None
        m = re.search(r'mate in (\d+)', desc)
        if m:
            mate_in_num = int(m.group(1))
        max_ply = mate_in_num * 2 + 2 if mate_in_num else 8

        # Mate in 1
        for move in board.legal_moves:
            san = board.san(move)
            board.push(move)
            if board.is_checkmate():
                board.pop()
                return {"puzzle_id": puzzle["id"], "best_move": san, "continuation": [san], "mate_in": 1}
            board.pop()

        # Mate in 2
        if max_ply >= 4:
            for move in board.legal_moves:
                san = board.san(move)
                board.push(move)
                if board.is_checkmate():
                    board.pop()
                    return {"puzzle_id": puzzle["id"], "best_move": san, "continuation": [san], "mate_in": 1}

                all_lead_to_mate = True
                reply_data = []
                for reply in board.legal_moves:
                    reply_san = board.san(reply)
                    board.push(reply)
                    found_mate = False
                    mate_san = None
                    for mm in board.legal_moves:
                        mm_san = board.san(mm)
                        board.push(mm)
                        if board.is_checkmate():
                            found_mate = True
                            mate_san = mm_san
                        board.pop()
                        if found_mate:
                            break
                    board.pop()
                    if not found_mate:
                        all_lead_to_mate = False
                        break
                    reply_data.append((reply_san, mate_san))

                if all_lead_to_mate and reply_data:
                    rs, ms = reply_data[0]
                    board.pop()
                    return {"puzzle_id": puzzle["id"], "best_move": san, 
                            "continuation": [san, rs, ms], "mate_in": 2}
                board.pop()

        # Mate in 3
        if max_ply >= 6:
            for move in board.legal_moves:
                san = board.san(move)
                board.push(move)
                if board.is_checkmate():
                    board.pop()
                    return {"puzzle_id": puzzle["id"], "best_move": san, "continuation": [san], "mate_in": 1}

                all_lead_to_mate = True
                reply_data = []
                for reply in board.legal_moves:
                    reply_san = board.san(reply)
                    board.push(reply)
                    found_mate_in_2 = False
                    mate_seq = None

                    for mm in board.legal_moves:
                        mm_san = board.san(mm)
                        board.push(mm)
                        if board.is_checkmate():
                            board.pop()
                            # Need all opponent replies to lead to mate
                            all_sub_lead = True
                            sub_reply_san = None
                            sub_mate_san = None
                            for sr in board.legal_moves:
                                sr_san = board.san(sr)
                                board.push(sr)
                                found_sub = False
                                sub_ms = None
                                for sm in board.legal_moves:
                                    sm_san = board.san(sm)
                                    board.push(sm)
                                    if board.is_checkmate():
                                        found_sub = True
                                        sub_ms = sm_san
                                    board.pop()
                                    if found_sub:
                                        break
                                board.pop()
                                if not found_sub:
                                    all_sub_lead = False
                                    break
                                sub_reply_san = sr_san
                                sub_mate_san = sub_ms
                            if all_sub_lead and sub_reply_san:
                                board.pop()
                                mate_seq = [mm_san, sub_reply_san, sub_mate_san]
                                found_mate_in_2 = True
                            else:
                                board.pop()
                            break
                        board.pop()
                        if found_mate_in_2:
                            break

                    if not found_mate_in_2:
                        all_lead_to_mate = False
                    else:
                        reply_data.append((reply_san, mate_seq))
                    board.pop()
                    if not all_lead_to_mate:
                        break

                if all_lead_to_mate and reply_data:
                    rs, ms = reply_data[0]
                    board.pop()
                    return {"puzzle_id": puzzle["id"], "best_move": san,
                            "continuation": [san, rs] + ms, "mate_in": 3}
                board.pop()

        return {"puzzle_id": puzzle["id"], "best_move": "", "continuation": [], "mate_in": None}

    # Best move by material gain
    piece_values = {chess.PAWN: 1, chess.KNIGHT: 3, chess.BISHOP: 3, chess.ROOK: 5, chess.QUEEN: 9, chess.KING: 0}

    best_move = None
    best_gain = -999999

    initial_wm = sum(piece_values[p.piece_type] for p in board.piece_map().values() if p.color == chess.WHITE)
    initial_bm = sum(piece_values[p.piece_type] for p in board.piece_map().values() if p.color == chess.BLACK)

    for move in board.legal_moves:
        san = board.san(move)
        board.push(move)
        wm = sum(piece_values[p.piece_type] for p in board.piece_map().values() if p.color == chess.WHITE)
        bm = sum(piece_values[p.piece_type] for p in board.piece_map().values() if p.color == chess.BLACK)
        score = (wm - bm) - (initial_wm - initial_bm)
        board.pop()
        if score > best_gain:
            best_gain = score
            best_move = san

    if best_move:
        board2 = chess.Board(fen)
        move_obj = board2.parse_san(best_move)
        cont = [best_move]
        board2.push(move_obj)
        for _ in range(3):
            if board2.is_game_over():
                break
            best_reply = None
            is_white_turn = board2.turn == chess.WHITE
            best_reply_score = -999999 if is_white_turn else 999999
            for move in board2.legal_moves:
                san = board2.san(move)
                board2.push(move)
                wm = sum(piece_values[p.piece_type] for p in board2.piece_map().values() if p.color == chess.WHITE)
                bm = sum(piece_values[p.piece_type] for p in board2.piece_map().values() if p.color == chess.BLACK)
                score = wm - bm
                board2.pop()
                if is_white_turn:
                    if score > best_reply_score:
                        best_reply_score = score
                        best_reply = san
                else:
                    if score < best_reply_score:
                        best_reply_score = score
                        best_reply = san
            if best_reply:
                cont.append(best_reply)
                move_obj = board2.parse_san(best_reply)
                board2.push(move_obj)
        return {"puzzle_id": puzzle["id"], "best_move": best_move, "continuation": cont, "mate_in": None}

    return {"puzzle_id": puzzle["id"], "best_move": "", "continuation": [], "mate_in": None}

def main():
    with open("/workdir/data/games.pgn") as f:
        pgn_text = f.read()
    with open("/workdir/data/puzzles.json") as f:
        puzzles = json.load(f)

    game_blocks = []
    current_game = []
    for line in pgn_text.split('\n'):
        if line.strip().startswith('[Event'):
            if current_game:
                game_blocks.append('\n'.join(current_game).strip())
            current_game = [line]
        else:
            current_game.append(line)
    if current_game:
        game_blocks.append('\n'.join(current_game).strip())

    repaired_games = []
    total_errors = 0
    for idx, block in enumerate(game_blocks):
        if not block.strip():
            continue
        result = repair_game(block.strip(), idx + 1)
        repaired_games.append(result)
        total_errors += len(result["errors_found"])
        print(f"Game {idx+1}: {result['errors_found']}", file=sys.stderr)

    puzzle_solutions = []
    for puzzle in puzzles:
        print(f"Puzzle {puzzle['id']}...", file=sys.stderr)
        sol = solve_puzzle(puzzle)
        puzzle_solutions.append(sol)
        print(f"  {sol}", file=sys.stderr)

    output = {
        "repaired_games": repaired_games,
        "puzzle_solutions": puzzle_solutions,
        "analysis_summary": {
            "games_processed": len(repaired_games),
            "errors_fixed": total_errors,
            "puzzles_solved": len(puzzle_solutions)
        }
    }

    with open("/workdir/chess_analysis.json", "w") as f:
        json.dump(output, f, indent=2)
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
